/// Looks up `id` in [`STID_FMTS`].
///
/// Ports upstream `find_sfid()` in `pvr_fw_trace.c`. A miss is `None`
/// rather than `ROGUE_FW_SF_LAST`: that sentinel's only job in upstream
/// is to mean "not in the table", which [`Option`] already says.
pub fn lookup(id: u32) -> Option<&'static StidFmt> {
    match STID_FMTS.binary_search_by_key(&id, |e| e.id) {
        Ok(i) => Some(&STID_FMTS[i]),
        Err(_) => None,
    }
}
